:root {
  /* Colors */
  --c-primary: #C23B22;
  --c-primary-light: #FDE8E5;
  --c-accent: #B8860B;
  --c-accent-light: #FDF3E0;
  --c-success: #3D7A4F;
  --c-success-light: #E8F0EB;
  --c-warning: #C2780A;
  --c-warning-light: #FFF8E1;
  --c-danger: #C23B22;
  --c-bg-paper: #F5F0E6;
  --c-bg-card: #FFFFFF;
  --c-bg-warm: #FAF6EF;
  --c-ink: #4A3728;
  --c-ink-light: #8B7355;
  --c-ink-lighter: #B8A890;
  --c-border: #E8DDCC;
  --c-border-subtle: #F0E8D8;
  /* Spacing */
  --sp-xs: 4px;
  --sp-sm: 8px;
  --sp-md: 16px;
  --sp-lg: 24px;
  --sp-xl: 48px;
  /* Typography */
  --t-heading: 1.3em;
  --t-body: 0.82em;
  --t-caption: 0.75em;
  /* Radii */
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 16px;
  /* Shadows */
  --sh-card: 0 1px 4px rgba(74,55,40,0.06);
  --sh-modal: 0 4px 24px rgba(74,55,40,0.12);
}
